insert into comparisons (slug, entity_a_id, entity_b_id, verdict_text, status) select 'arsenal-boston-celtics', ea.id, eb.id, 'Old money, self-serious, and finally young and good again.', 'seed' from entities ea, entities eb where ea.slug='arsenal' and eb.slug='boston-celtics' on conflict (slug) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'pedigree', 'Most-decorated old-money institution in the league, identity over flash.' from comparisons where slug='arsenal-boston-celtics' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'trajectory', 'Came through a long painful rebuild, now a young elite core that''s finally arrived.' from comparisons where slug='arsenal-boston-celtics' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'fanbase', 'Demanding, self-serious, convinced of their own sophistication.' from comparisons where slug='arsenal-boston-celtics' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'city', 'Cosmopolitan capital, knows it''s a big deal.' from comparisons where slug='arsenal-boston-celtics' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'aura', 'Expectation is the air they breathe.' from comparisons where slug='arsenal-boston-celtics' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'style', 'Structured, principled, occasionally too clever for its own good.' from comparisons where slug='arsenal-boston-celtics' on conflict (comparison_id, dimension) do nothing;
insert into comparisons (slug, entity_a_id, entity_b_id, verdict_text, status) select 'manchester-united-la-lakers', ea.id, eb.id, 'The biggest badge in the sport, currently worn by the wrong team.', 'seed' from entities ea, entities eb where ea.slug='manchester-united' and eb.slug='la-lakers' on conflict (slug) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'pedigree', 'The biggest brand and the most glamour, titles as a birthright.' from comparisons where slug='manchester-united-la-lakers' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'trajectory', 'Coasting on reputation while the product flails.' from comparisons where slug='manchester-united-la-lakers' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'fanbase', 'Global, frontrunner-heavy, allergic to mid-table.' from comparisons where slug='manchester-united-la-lakers' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'city', 'Industrial roots, showbiz self-image.' from comparisons where slug='manchester-united-la-lakers' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'aura', 'Expects to win because of the badge, not the team.' from comparisons where slug='manchester-united-la-lakers' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'style', 'Signs names, not systems.' from comparisons where slug='manchester-united-la-lakers' on conflict (comparison_id, dimension) do nothing;
insert into comparisons (slug, entity_a_id, entity_b_id, verdict_text, status) select 'manchester-city-golden-state-warriors', ea.id, eb.id, 'The machine that solved the sport and got resented for it.', 'seed' from entities ea, entities eb where ea.slug='manchester-city' and eb.slug='golden-state-warriors' on conflict (slug) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'pedigree', 'Decades as the noisy neighbour, then a dynasty built in a lab.' from comparisons where slug='manchester-city-golden-state-warriors' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'trajectory', 'From punchline to perennial favourite in one ownership change.' from comparisons where slug='manchester-city-golden-state-warriors' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'fanbase', 'New arrivals everywhere, old heads who remember the bad years and never let you forget it.' from comparisons where slug='manchester-city-golden-state-warriors' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'city', 'Second club of a first-class city that now runs the place.' from comparisons where slug='manchester-city-golden-state-warriors' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'aura', 'Wins so routinely it made winning boring — and everyone else furious.' from comparisons where slug='manchester-city-golden-state-warriors' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'style', 'Pass-move geometry; the system is the superstar.' from comparisons where slug='manchester-city-golden-state-warriors' on conflict (comparison_id, dimension) do nothing;
insert into comparisons (slug, entity_a_id, entity_b_id, verdict_text, status) select 'liverpool-san-antonio-spurs', ea.id, eb.id, 'Culture as a weapon: the institution outlasts every star.', 'seed' from entities ea, entities eb where ea.slug='liverpool' and eb.slug='san-antonio-spurs' on conflict (slug) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'pedigree', 'A trophy room built by dynasties, then a long wait that made the next one taste holy.' from comparisons where slug='liverpool-san-antonio-spurs' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'trajectory', 'Reloaded around a beloved coach''s system and kept competing after he left.' from comparisons where slug='liverpool-san-antonio-spurs' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'fanbase', 'Evangelical, communal, will tell you about the good old days unprompted.' from comparisons where slug='liverpool-san-antonio-spurs' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'city', 'Port city with a chip on its shoulder and a song for everything.' from comparisons where slug='liverpool-san-antonio-spurs' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'aura', 'Big European nights are their natural habitat.' from comparisons where slug='liverpool-san-antonio-spurs' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'style', 'Relentless collective pressing — eleven players, one organism.' from comparisons where slug='liverpool-san-antonio-spurs' on conflict (comparison_id, dimension) do nothing;
insert into comparisons (slug, entity_a_id, entity_b_id, verdict_text, status) select 'chelsea-brooklyn-nets', ea.id, eb.id, 'New money bought a seat at the table, then set the table on fire.', 'seed' from entities ea, entities eb where ea.slug='chelsea' and eb.slug='brooklyn-nets' on conflict (slug) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'pedigree', 'History before the takeover is a pub-quiz question; everything real is post-money.' from comparisons where slug='chelsea-brooklyn-nets' on conflict (comparison_id, dimension) do nothing;
insert into comparison_dimensions (comparison_id, dimension, rationale_text) select id, 'trajectory', 'Superteam, blow it up, superteam again — chaos as a business model.' from comparisons where slug='chelsea-brooklyn-nets' on conflict (comparison_id, dimension) do nothing;
